import bcrypt

def generate_bcrypt_password(password: str) -> str:
    # 生成盐，设置轮数为10
    salt = bcrypt.gensalt(rounds=10)
    # 哈希密码
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_password.decode('utf-8')

