	return (token >= T_AUTO && token <= T_STATIC);
}

unsigned get_storage(unsigned dflt)
{
	unsigned t;
	skip_modifiers();
	if (!is_storage_word())
		return dflt;
	t = token;
	next_token();
	switch (t) {
	case T_AUTO:
		return S_AUTO;
	case T_REGISTER:
		return S_REGISTER;
	case T_STATIC:
		if (dflt == S_AUTO)
			return S_LSTATIC;
		else
			return S_STATIC;
	case T_EXTERN:
		return S_EXTERN;
	}
	/* gcc */
	return 0;
}

/*
 *	Storage I/O - hacks for now
 */

void put_typed_data(struct node *n)
{
	unsigned op = n->op;
	register unsigned t = n->type;
	/* Collapse array types down to their underlying type so the backend
	   can use the correct pointer types on a word/byteptr machine */
	if (IS_ARRAY(t) && PTR(t) == 0)
		t = PTRTO + array_type(t);
	/* Allow for implied casting in the declaration on word machines. For
	   example  "int *x = (int *)charptr;" */
	if (op == T_CAST && PTR(t) && PTR(n->right->type)) {
		n = n->right;
		op = n->op;
	}
	out_block("%[", 2);
	if (op != T_CASELABEL && op != T_PAD && op != T_LABEL &&
		op != T_NAME && op != T_CONSTANT)
		notconst();
	n->type = t;
	out_block(n, sizeof(struct node));
}

void put_padding_data(unsigned space)
{
	register struct node *n = make_constant(space, UINT);
	n->op = T_PAD;
	put_typed_data(n);
	free_node(n);
}

void put_typed_constant(unsigned type, unsigned long value)
{
	struct node *n = make_constant(value, type);
	put_typed_data(n);
	free_node(n);
}

void put_typed_case(unsigned tag, unsigned entry)
{
	register struct node *n = make_constant(tag, PTRTO|VOID);
	n->op = T_CASELABEL;
	n->val2 = entry;
	put_typed_data(n);
	free_node(n);
}

#include "compiler.h"

static unsigned volatiles[NUM_VOLATILE];
static unsigned *nextv = volatiles;

unsigned is_volatile(register unsigned sym)
{
    register unsigned *p = volatiles;
    while(p != nextv)
        if (*p++ == sym)
            return 1;
    return 0;
}

void add_volatile(unsigned sym)
{
    if (is_volatile(sym))
        return;
    if (nextv == &volatiles[NUM_VOLATILE])
        error("too many volatiles");
    *nextv++ = sym;
}

/*
 *	Compiler pass support for the target processor
 */

#include "compiler.h"

unsigned target_ptr = UINT;

unsigned target_alignof(unsigned t, unsigned storage)
{
    /* Arguments are stacked as words on 8080 */
    if (storage == S_ARGUMENT)
	return 2;
    return 1;
}

/* Size of primitive types for this target */
static unsigned sizetab[16] = {
	1, 2, 4, 8,		/* char, short, long, longlong */
	1, 2, 4, 8,		/* unsigned forms */
	4, 8, 0, 0,		/* float, double, void, unused.. */
	0, 0, 0, 0		/* unused */
};

unsigned target_sizeof(unsigned t)
{
	unsigned s;

	if (PTR(t))
		return 2;

	s = sizetab[(t >> 4) & 0x0F];
	if (s == 0) {
		error("cannot size type");
		s = 1;
	}
	return s;
}

/* 8086 convention is to push char as word */
unsigned target_argsize(unsigned t)
{
	unsigned s = target_sizeof(t);
	if (s == 1)
		return 2;
	return s;
}

/* integer type for a pointer of type t. For most platforms this is trivial
   but strange boxes with word addressing and byte pointers may need help */
unsigned target_ptr_arith(unsigned t)
{
	return CINT;
}

/* Adjust scaling for a pointer of type t. For most systems this is a no-op
   but on machines with things like word addressing it isn't.*/

unsigned target_scale_ptr(unsigned t, unsigned scale)
{
	return scale;
}

/* Scale a pointer offset to byte size */
unsigned target_ptroff_to_byte(unsigned t)
{
	return 1;
}

struct node *target_struct_ref(struct node *n, unsigned type, unsigned off)
{
	n->type = PTRTO + type;
	n = tree(T_PLUS, n, make_constant(off, UINT));
	n->type = type;
	return n;
}

/* Can we remove pointer/int casts for fixed objects */
unsigned target_remove_cast(struct node *l, struct node *r)
{
	return 1;
}

/* Remap any base types for simplicity on the platform */
unsigned target_type_remap(unsigned type)
{
	/* Our double is float */
	if (type == DOUBLE)
		return FLOAT;
	return type;
}

